// Rosie, the trainer's guide: a small anime-style rose adapted from the Cal
// Poly Rose Float logo (see docs/GUIDE_DESIGN.md for the sources). Everything
// she says lives here, so her name and her lines can be changed in one place.
// The teaching text itself (explanations, instructions, questions, feedback)
// stays in the lessons; Rosie frames it, she does not replace it.

export const MASCOT = Object.freeze({
  name: 'Rosie',
  dir: 'assets/mascot/',
  file: 'rosie',
});

// One bundled SVG per expression (generated by scripts/build-mascot.mjs).
export const EXPRESSIONS = Object.freeze(['wave', 'point', 'happy', 'cheer', 'oops']);

// The sprite fallback has five drawings; every richer expression name maps onto one of them.
const SPRITE_FOR = Object.freeze({
  wave: 'wave', point: 'point', happy: 'happy', cheer: 'cheer', oops: 'oops', idle: 'happy',
  neutral: 'happy', alertness: 'point', wonder: 'wave', surprise: 'wave', shock: 'oops',
  satisfaction: 'happy', amusement: 'happy', joy: 'cheer', laughter: 'cheer',
  concern: 'oops', anxiety: 'oops', fear: 'oops', terror: 'oops',
  dejection: 'oops', melancholy: 'oops', sadness: 'oops', grief: 'oops',
  sternness: 'point', indignation: 'point', anger: 'oops', rage: 'oops',
  disdain: 'point', aversion: 'oops', disgust: 'oops', revulsion: 'oops',
  curious: 'point', reassuring: 'happy', sheepish: 'oops', nerdy: 'point', tickled: 'cheer',
});

export function spriteFor(expression) {
  return SPRITE_FOR[expression] || 'happy';
}

export function mascotSrc(expression) {
  const sprite = SPRITE_FOR[expression];
  if (!sprite) throw new RangeError(`Unknown mascot expression ${expression}`);
  return `${MASCOT.dir}${MASCOT.file}-${sprite}.svg`;
}

// The first-launch welcome: three short beats, skippable at any time.
export const WELCOME = Object.freeze([
  Object.freeze({
    expression: 'wave',
    text: 'Hi, I’m Rosie, the Rose Float rose. I’ll show you how the team programs the float in PC•MACs. The windows beside each lesson are a recreation of the real PC•MACs windows, and nothing here connects to real equipment.',
    button: 'Next',
  }),
  Object.freeze({
    expression: 'point',
    text: 'Every step works the same way. I point at one thing, show it being done, then you do it in the same window. I tell you right away whether it worked, and what to fix if it didn’t.',
    button: 'Next',
  }),
  Object.freeze({
    expression: 'happy',
    text: 'If you get stuck, rest the pointer on any control for a hint, press Help ? and then click the control, or search the Handbook. Ready? Start with Basic: it covers enough to get by.',
    button: 'Let’s go',
  }),
]);

